package com.example.jobfinderapp.activities;import android.os.*;import android.widget.*;import androidx.appcompat.app.*;import com.example.jobfinderapp.R;import com.example.jobfinderapp.database.DBHelper;import com.example.jobfinderapp.models.User;import com.example.jobfinderapp.utils.UserSession;
public class UserDetailActivity extends AppCompatActivity{DBHelper db;int id,actor;TextView info;public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_user_detail);db=DBHelper.getInstance(this);id=getIntent().getIntExtra("USER_ID",-1);actor=getIntent().getIntExtra("ACTOR_ID",-1);UserSession s=new UserSession(this);User admin=db.getUserById(s.getUserId());if(admin==null||!DBHelper.ROLE_ADMIN.equals(admin.getRole())||!DBHelper.STATUS_ACTIVE.equals(admin.getStatus())){finish();return;}info=findViewById(R.id.tvUserDetail);findViewById(R.id.btnToggleUser).setOnClickListener(v->toggle());load();}void load(){User u=db.getUserById(id);if(u==null){finish();return;}info.setText(u.getFullname()+"\n"+u.getEmail()+"\n"+String.valueOf(u.getPhone())+"\nVai trò: "+u.getRole()+"\nTrạng thái: "+u.getStatus()+"\nĐơn ứng tuyển: "+db.getCandidateApplicationCount(id)+"\nTin tuyển dụng: "+db.getEmployerJobCount(id));((Button)findViewById(R.id.btnToggleUser)).setText(DBHelper.STATUS_BLOCKED.equals(u.getStatus())?"Mở khóa":"Khóa tài khoản");}void toggle(){User u=db.getUserById(id);if(u==null)return;String next=DBHelper.STATUS_BLOCKED.equals(u.getStatus())?DBHelper.STATUS_ACTIVE:DBHelper.STATUS_BLOCKED;if(db.updateUserStatusByAdmin(id,next,actor))load();}}
